  trash 0 15
  + $lvl 0
}

proc deep {lvl, max} {
  if [> $lvl $max] {
    0
  } else {
    trash 0 10
    def lv $lvl
    def f [spawn { work $lv }]
    def r [await $f]
    def rest [deep [+ $lvl 1] $max]
    + $r $rest
  }
}

